import {readHousehold,writeHousehold} from './household.js';
import {householdQuantity} from './household-units.js';
import {initializeLanguages,languageControl,toEnglishSearch,translate,getLocale} from './i18n.js';
import {VERSION,MODES,MEALS,CATEGORIES,norm,slug,dayKey,addDays,monday,esc,currency,uid,headcount,eligible,recommend,searchSummary,parseSearch,scaleRecipe,scaleSuitability,grocery,quantity,planWeek,productionPlan,coordinatedMenu,lockedUntil,vegetarianText,ROOTS,preferenceScore} from './core.js';
import {KitchenStore,supabaseRemote} from './storage.js';
import {cachedJSON,loadCategory,loadCategories,dishes,getRecipe} from './catalog.js';
import {dishPhoto,photoCredit} from './photos.js';
import {shoppingList,skillStep} from './intelligence.js';
import {installFeatures} from './features.js';
let features;

const $=s=>document.querySelector(s);
const defaults={mode:'home',adults:2,kids:0,guests:0,jainMeals:0,buffer:0,budget:100,eventType:'Wedding',service:'Buffet',meal:'Dinner'};
let household=readHousehold(localStorage,null,defaults);
let party=household.party,filters={category:'Dinner',cuisine:'Any',time:0,effort:'',jain:household.jain,query:''};
let currentView='today',client,user,store,config,authEpoch=0,authMode='login',manifest,aliases={},week=monday(),results=[],visible=12,basket=[],syncState={},installPrompt,activeRecipe,recipeParty,step=0,timers=[],saveCallback,planTarget,searchVersion=0;
let searchCompleted=false;
const explicitFilters=new Set();
const icon={today:'⌂',discover:'✦',planner:'▦',combos:'♡',pantry:'◉',family:'♧',insights:'◴',settings:'⚙',more:'•••'};
const navs={today:'Today',discover:'Discover',planner:'My week',combos:'My menus',pantry:'Pantry',family:'Family',insights:'Insights',settings:'Settings',more:'More'};
const emoji=d=>d?.method==='coffee'?'☕':d?.method==='tea'?'🍵':d?.method==='blend'?'🥭':d?.method==='dessert'?'🍨':d?.method==='dal'?'🥣':d?.method==='flatbread'?'🫓':d?.method==='rice'?'🍚':d?.method==='assemble'?'🥗':'🍲';
const opts=(arr,value)=>arr.map(x=>`<option value="${esc(typeof x==='object'?x[0]:x)}" ${String(typeof x==='object'?x[0]:x)===String(value)?'selected':''}>${esc(typeof x==='object'?x[1]:x)}</option>`).join('');
const empty=(title,text,action='discover',label='Explore dishes')=>`<div class="empty"><span>✧</span><h3>${esc(title)}</h3><p>${esc(text)}</p><button class="primary" data-action="${action}">${esc(label)}</button></div>`;
const canonical=id=>aliases[id]||id;
function state(){
 const get=k=>store?.get(k)||[];
 const map=k=>Object.fromEntries(get(k).map(x=>[canonical(x.dishId||x._id.split(':').slice(1).join(':')),x.value??x]));
 return {favorites:get('favorite').map(x=>canonical(x.dishId)),hidden:get('hidden').map(x=>canonical(x.dishId)),history:get('history').map(h=>({...h,dishId:canonical(h.dishId),dishIds:(h.dishIds||[h.dishId]).map(canonical)})),pantry:get('pantry'),leftovers:get('leftover'),exclusions:store?.value('config:exclusions',household.exclusions)||household.exclusions,family:get('family'),ratings:map('rating'),votes:map('vote'),preferences:map('preference'),plans:get('plan'),combos:get('combo'),custom:get('recipe'),recurrences:get('recurrence')};
}
async function saveHousehold(){
 household={...household,party:{...party},jain:!!filters.jain};
 const saved={...household,party:{...party}};writeHousehold(localStorage,user?.id,saved);
 const ownerStore=store,ownerId=user?.id;if(ownerId&&ownerStore){await ownerStore.put('config','config:household',{confirmed:saved.confirmed,jain:saved.jain,metric:saved.metric});if(user?.id!==ownerId||store!==ownerStore)return;await ownerStore.put('config','config:party',saved.party);}
}
const displayQuantity=i=>householdQuantity(i,household.metric);
function renderMore(){return heading('YOUR KITCHEN','More','Everything for your household.')+`<div class="settings-grid">${['pantry','family','insights','settings'].map(key=>`<button class="panel" data-nav="${key}">${icon[key]} ${navs[key]}</button>`).join('')}</div>`;}
function currentFilters(){return {...filters,party,budget:party.budget,equipment:store?.value('config:equipment',[])||[],weather:store?.value('config:weather',{kind:'pleasant'})?.kind};}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function error(e){notify(e?.message||String(e));}
function modal(title,body){$('#dialogBody').innerHTML=`<div class="modal-heading"><div><span class="eyebrow">KAVITA KA KITCHEN</span><h2 id="dialogTitle">${esc(title)}</h2></div>${languageControl()}<button class="icon-btn" data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!$('#dialog').open)$('#dialog').showModal();features?.decorateModal();}
function close(){if($('#dialog').open)$('#dialog').close();saveCallback=null;}
function requireUser(){if(user&&store)return true;authMode='login';showAuth();return false;}
async function put(kind,id,payload){if(!requireUser())return false;await store.put(kind,id,payload);return true;}
function nav(view){currentView=view;render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#main').focus({preventScroll:true});}
function render(){
 $('#nav').innerHTML=Object.entries(navs).filter(([key])=>key!=='more').map(([key,label])=>`<button data-nav="${key}" class="nav-link ${key===currentView?'active':''}" ${key===currentView?'aria-current="page"':''}><span aria-hidden="true">${icon[key]}</span>${label}${key==='combos'&&state().combos.length?`<small>${state().combos.length}</small>`:''}</button>`).join('');
 $('#mobileNav').innerHTML=['today','discover','planner','combos','more'].map(key=>`<button data-nav="${key}" class="${key===currentView?'active':''}"><span aria-hidden="true">${icon[key]}</span>${navs[key]}</button>`).join('');
 $('#kitchenButton').innerHTML=`<span aria-hidden="true">${{home:'⌂',office:'▥',factory:'▤',event:'♧'}[party.mode]}</span> ${MODES[party.mode]} <span aria-hidden="true">⌄</span>`;
 const profile=store?.value('profile:me',{});$('#accountButton').textContent=user?(profile?.name||user.email?.split('@')[0]||'My account'):'Sign in';
 $('#accountButton').className=user?'account-btn':'primary small';
 $('#main').innerHTML=({today:renderToday,discover:renderDiscover,planner:renderPlanner,combos:renderCombos,pantry:renderPantry,family:renderFamily,insights:renderInsights,settings:renderSettings,more:renderMore,grocery:renderGroceryLoading,privacy:renderPrivacy,terms:renderTerms,'delete-account':renderDeletionPage}[currentView]||renderToday)();
 updateSync();features?.decorate();if(currentView==='grocery')fillGrocery();
}
function heading(kicker,title,copy,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${copy}</p></div>${actions}</div>`;}
function renderToday(){
 const name=store?.value('profile:me',{})?.name||'',hour=new Date().getHours(),greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';
 const s=state(),featured=(manifest?.featured||[]).filter(d=>eligible(d,currentFilters(),s)),today=s.plans.filter(p=>p.date===dayKey());
 return `<div class="welcome"><div><span class="eyebrow">A LITTLE PLANNING. A LOT OF JOY.</span><h1><span>${greeting}</span>${name?', <span data-user-content>'+esc(name)+'</span>':''}<span class="sun"> ✺</span></h1><p>Something delicious starts here.</p></div><span class="date-label">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span></div>
 <section class="hero"><div class="hero-copy"><span class="badge light">100% vegetarian · Always eggless</span><h2>Good food.<br>Less <em>what if.</em></h2><p>Everyday meals for you and the people you love.<br class="desktop-only"> Let’s find what feels right today.</p><form id="heroSearch" class="search-box"><span aria-hidden="true">⌕</span><input name="query" aria-label="What do you feel like eating?" placeholder="What do you feel like eating?" maxlength="200"><button aria-label="Find food ideas" class="search-go">→</button></form><div class="hero-hints"><button data-action="quick" data-value="Light Meals">Something light</button><button data-action="quick" data-value="Quick Meals">Under 30 minutes</button><button data-action="surprise">Surprise me ✧</button></div></div><div class="hero-art" aria-hidden="true"><img src="/art/kitchen-bowl.svg" alt="" width="440" height="400"><span class="art-label">A little variety.<br>A happier table.</span></div></section>
 <div class="quick-grid"><button class="quick-card" data-action="headcount"><span class="quick-icon peach">♧</span><span><small>YOUR KITCHEN</small><b>${esc(MODES[party.mode])}</b><span>${headcount(party).servings} servings · Edit headcount</span></span><i>↗</i></button><button class="quick-card" data-nav="planner"><span class="quick-icon sage">▦</span><span><small>MAKE ROOM FOR YOUR WEEK</small><b>Plan once. Eat well.</b><span>${s.plans.length?'Your calendar is taking shape':'A calmer week starts with a plan'}</span></span><i>↗</i></button><button class="quick-card" data-nav="pantry"><span class="quick-icon lavender">♻</span><span><small>A LITTLE LESS WASTE</small><b>Use what you have</b><span>${s.pantry.length+s.leftovers.length} pantry & leftover items</span></span><i>↗</i></button></div>
 <section class="section"><div class="section-title"><div><span class="eyebrow">YOUR DAILY RHYTHM</span><h2>On the table today</h2></div><button class="text-btn" data-nav="planner">See my week →</button></div><div class="today-grid">${MEALS.map((meal,i)=>{const entry=today.find(x=>x.meal===meal);return `<button class="today-meal" data-action="today-meal" data-value="${meal}"><span class="meal-label">${['☀','◒','☾'][i]} ${meal}</span><b>${esc(entry?.name||'A delicious possibility')}</b><span>${entry?`${headcount(entry.party||party).servings} servings`:'＋ Add a little inspiration'}</span></button>`;}).join('')}</div></section>
 <section class="section"><div class="section-title"><div><span class="eyebrow">SIMPLE THINGS, DONE WELL</span><h2>A little inspiration</h2><p>Recipes to make your everyday a little more delicious.</p></div><button class="text-btn" data-nav="discover">Explore all dishes →</button></div><div class="inspiration-grid">${featured.slice(0,4).map(card).join('')||'<p>Loading inspiration…</p>'}</div></section>
 <section class="green-strip"><div><span class="eyebrow">YOUR NEXT FAVOURITE IS OUT THERE</span><h2>One kitchen. A world of possibilities.</h2><p>Discover regional Indian favourites and eggless dishes from around the world.</p></div><button class="secondary" data-action="world">Explore cuisines ↗</button></section>`;
}
function card(d){const fav=state().favorites.includes(d.id),score=scaleSuitability(d,headcount(party).servings,party.mode);return `<article class="dish-card" draggable="true" data-dish="${esc(d.id)}"><div class="dish-art art-${['sage','peach','lavender','yellow'][d.name.length%4]}"><button class="art-open" data-action="recipe" data-id="${esc(d.id)}" aria-label="Open ${esc(d.name)} recipe">${dishPhoto(d)}</button><button class="heart ${fav?'selected':''}" data-action="favorite" data-id="${esc(d.id)}" aria-label="${fav?'Remove favourite':'Favourite'} ${esc(d.name)}">${fav?'♥':'♡'}</button><span class="time-badge">◷ ~${d.time} min${d.advancePrep?" + resting":""}</span></div><div class="dish-content"><span class="dish-cuisine">${esc(d.cuisine)}${d.exact===false?' · SUGGESTION':''}</span><h3><button data-action="recipe" data-id="${esc(d.id)}">${esc(d.name)}</button></h3><div class="tags"><span>${d.recipeStatus==='complete'?'Full recipe':'Preparation outline'}</span>${d.jainVerified?'<span>Jain ingredients</span>':''}${party.mode!=='home'?`<span>${score}/10 bulk fit</span>`:''}</div><div class="dish-foot"><button class="text-btn" data-action="basket" data-id="${esc(d.id)}">${basket.includes(d.id)?'✓ In menu':'+ Add to menu'}</button><button class="more-btn" data-action="dish-more" data-id="${esc(d.id)}" aria-label="More options for ${esc(d.name)}">•••</button></div></div></article>`;}
function renderDiscover(){
 const counts=searchSummary(results,visible);
 const notice=searchCompleted&&!counts.matched?(counts.total?`No dishes matched that. Showing ${esc(filters.category)} ideas instead. Your selected filters still apply.`:'No dishes matched that. Try another search or change your selected filters.'):'';
 return heading('FOLLOW YOUR APPETITE','What sounds good?','Your next favourite, with all your food rules respected.',`<button class="secondary" data-action="custom">＋ Family recipe</button>`)+
 `${notice?`<div class="info-panel search-notice" role="status"><strong>${notice}</strong></div>`:''}<form id="discoverForm" class="discover-search"><div class="search-box"><span>⌕</span><input name="query" value="${esc(filters.query)}" placeholder="Try: Punjabi dinner for 6 adults, no potato" aria-label="Search dishes" maxlength="200"><button class="primary">Find ideas →</button></div><div class="filter-bar"><label>Category<select name="category">${opts(CATEGORIES,filters.category)}</select></label><label>Cuisine<select name="cuisine">${opts(['Any',...(manifest?.cuisines||[])],filters.cuisine)}</select></label><label>Cooking time<select name="time">${opts([[0,'No limit'],[15,'15 minutes'],[30,'30 minutes'],[45,'45 minutes'],[60,'60 minutes']],filters.time)}</select></label><label>Effort<select name="effort">${opts([['','Any effort'],['easy','Easy'],['medium','Normal'],['special','Special effort']],filters.effort)}</select></label><label class="check-pill"><input name="jain" type="checkbox" ${filters.jain?'checked':''}>Strict Jain</label><button type="button" class="text-btn" data-action="exclusions">Exclusions${state().exclusions.length?' ('+state().exclusions.length+')':''}</button></div></form>
 <div class="discover-tools"><span>${headcount(party).servings} servings · ${esc(MODES[party.mode])}</span><div><button class="text-btn" data-action="surprise">✧ Surprise me</button><button class="text-btn" data-action="coordinated">Build a complete menu</button><button class="text-btn" data-action="basket-open">My selection (${basket.length})</button></div></div>
 <div class="section-title"><div><h2>${searchCompleted?`${counts.total} dishes`:'A whole world of good food'}</h2><p>${searchCompleted?`${counts.matched} matches · ${counts.suggestions} suggestions · Showing ${counts.shown} of ${counts.total} · ${counts.remaining} remaining`:'Choose what you feel like. Your saved household size and food rules apply.'}</p></div></div>
 <div class="results-grid">${results.length?results.slice(0,visible).map(card).join(''):searchCompleted?'<p>No dishes fit this search and your selected filters.</p>':empty('Let’s find your next meal','Use the search above, or start with dinner inspiration.','search','Find dinner ideas')}</div>
 ${counts.remaining?`<div class="load-more"><button class="secondary" data-action="more">Show ${counts.next} more ideas ↓</button></div>`:''}`;
}
function renderPlanner(){const s=state();return heading('A CALMER WEEK','Make space for good food.','Breakfast, lunch, dinner. A little decision made ahead.',`<button class="primary" data-action="plan-week">✦ Plan my week</button>`)+
 `<div class="calendar-toolbar"><button class="icon-btn" data-action="week-prev" aria-label="Previous week">←</button><h2>${new Date(week+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})} – ${new Date(addDays(week,6)+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</h2><button class="icon-btn" data-action="week-next" aria-label="Next week">→</button><div class="spacer"></div><button class="text-btn" data-action="this-week">This week</button><button class="secondary" data-action="copy-week">Copy previous week</button><button class="secondary" data-nav="grocery">Grocery list ↗</button></div>
 <div class="calendar-scroll"><div class="week-calendar"><div class="calendar-corner">MEAL</div>${Array.from({length:7},(_,i)=>{const date=addDays(week,i);return `<div class="calendar-day ${date===dayKey()?'is-today':''}"><b>${new Date(date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'short'})}</b><span>${new Date(date+'T12:00:00').getDate()}</span><button class="text-btn" data-action="day-menu" data-date="${date}" aria-label="Day options for ${date}">•••</button></div>`;}).join('')}${MEALS.map(meal=>`<div class="meal-axis">${meal}</div>${Array.from({length:7},(_,i)=>{const date=addDays(week,i),p=s.plans.find(x=>x.date===date&&x.meal===meal);return `<button class="calendar-slot ${p?'filled':''}" data-action="slot" data-date="${date}" data-meal="${meal}" aria-label="${date} ${meal}: ${esc(p?.name||'Add meal')}">${p?`<span>${esc(p.name)}</span><small>${headcount(p.party||party).servings} servings</small>`:'<span class="slot-plus">＋</span><small>Add meal</small>'}</button>`;}).join('')}`).join('')}</div></div>
 <div class="info-panel"><span>✧</span><div><b>Good plans leave room for life.</b><p>Drag a dish into a day, add a saved menu, duplicate a day or generate the week. Your exclusions and 8-day rotation are checked when adding meals.</p></div></div>`;}
function renderCombos(){const s=state();return heading('KEEP THE GOOD ONES','Your menus, made personal.','From Saturday dinner to a celebration for hundreds.',`<button class="primary" data-action="combo-new">＋ Create a menu</button>`)+`<div class="section-title"><h2>Saved combinations <span class="count">${s.combos.length}</span></h2></div><div class="combo-grid">${s.combos.length?s.combos.map(c=>`<article class="combo-card"><div class="combo-symbol">${c.favorite?'♥':'♧'}</div><span class="eyebrow">${esc(c.cuisine||'YOUR KITCHEN')} · ${esc(MODES[c.party?.mode||'home'])}</span><h2>${esc(c.name)}</h2><p>${(c.dishNames||[]).map(esc).join(' · ')}</p><div class="tags"><span>${headcount(c.party||party).servings} servings</span><span>${esc(c.occasion||'Everyday')}</span></div><div class="button-row"><button class="primary small" data-action="combo-reuse" data-id="${esc(c._id)}">Reuse this menu</button><button class="text-btn" data-action="combo-edit" data-id="${esc(c._id)}">Edit</button><button class="text-btn" data-action="combo-more" data-id="${esc(c._id)}">•••</button></div></article>`).join(''):empty('A good meal deserves an encore.','Add dishes to a menu, give it a name and make it yours.','combo-new','Create my first menu')}</div><div class="section-title section"><div><span class="eyebrow">YOUR MEAL MEMORY</span><h2>Past menus & cooked meals</h2></div></div><div class="timeline">${s.history.length?s.history.sort((a,b)=>b.date.localeCompare(a.date)).map(h=>`<article class="history-row"><span class="history-date">${new Date(h.date).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span><div><h3>${esc(h.name)}</h3><p>${esc(h.comments||'')}${h.party?' · '+headcount(h.party).servings+' servings':''}${h.cost?' · '+currency(h.cost):''}${h.rating?' · '+h.rating+'/5':''}</p><small>${h.dishIds?.map(id=>dishes.get(id)).filter(Boolean).map(d=>{const until=lockedUntil(d,[h]);return until?'🔒 '+d.name+' available '+new Date(until).toLocaleDateString():'';}).filter(Boolean).map(esc).join(' · ')||''}</small></div><button class="text-btn" data-action="history-reuse" data-id="${esc(h._id)}">Reuse →</button></article>`).join(''):empty('Your story starts with a meal.','Mark a dish or menu as cooked to remember it here.','discover','Find something delicious')}</div>`;}
function renderPantry(){const s=state();const rows=(items,kind)=>items.map(x=>`<article class="stock-row"><div class="stock-icon">${kind==='pantry'?'◉':'♻'}</div><div><b>${esc(x.name)}</b><p>${esc(x.quantity||'')}${x.expiry?' · Best before '+esc(x.expiry):''}</p>${x.expiry&&x.expiry<=addDays(dayKey(),1)?`<span class="badge peach">${x.expiry<dayKey()?'Past date — check before using':x.expiry===dayKey()?'USE TODAY':'USE TOMORROW'}</span>`:''}</div><button class="text-btn" data-action="stock-remove" data-id="${esc(x._id)}" aria-label="Remove ${esc(x.name)}">×</button></article>`).join('');return heading('MAKE THE MOST OF WHAT’S HERE','Good food. Less waste.','Keep ingredients and leftovers in view.',`<button class="primary" data-action="stock-add" data-kind="pantry">＋ Add ingredients</button>`)+`<div class="two-columns"><section class="panel"><div class="section-title"><h2>In your pantry</h2><button class="text-btn" data-action="pantry-search">Find matches →</button></div>${rows(s.pantry,'pantry')||'<p class="muted">A little stock check goes a long way. Add what you have.</p>'}</section><section class="panel"><div class="section-title"><h2>A second delicious life</h2><button class="text-btn" data-action="stock-add" data-kind="leftover">＋ Leftovers</button></div>${rows(s.leftovers,'leftover')||'<p class="muted">Leftover rice, dal or roti? Keep it in the plan.</p>'}<button class="secondary" data-action="leftover-search">Discover leftover ideas ♻</button></section></div><div class="info-panel"><span>◉</span><div><b>Use dates as reminders.</b><p>Check freshness and storage before cooking. Expired or uncertain leftovers should not be used just to reduce waste. Use Scan pantry photo when AI is enabled, then review the identified ingredients before adding them.</p></div></div>`;}
function renderFamily(){const s=state();return heading('EVERY TASTE HAS A PLACE','Meet your table.','Likes, dislikes and the people behind your favourite meals.',`<button class="primary" data-action="family-add">＋ Add a member</button>`)+`<div class="combo-grid">${s.family.map(p=>`<article class="panel"><span class="avatar">${esc(p.name[0])}</span><h2>${esc(p.name)}</h2><p>${p.child?'Child':'Adult'} · ${esc(p.spice||'Mild')} spice</p><p><b>Loves</b> ${esc(p.likes?.join(', ')||'Still discovering')}</p><p><b>Dislikes</b> ${esc(p.dislikes?.join(', ')||'None added')}</p><p>${esc(p.diet||'Vegetarian, eggless')}</p><div class="button-row"><button class="text-btn" data-action="family-edit" data-id="${esc(p._id)}">Edit</button><button class="text-btn danger-text" data-action="stock-remove" data-id="${esc(p._id)}">Remove</button></div></article>`).join('')||empty('Who makes your kitchen yours?','Add family members to build taste preferences and record votes.','family-add','Add a family member')}</div><div class="info-panel"><span>♡</span><div><b>Preferences learn as you cook.</b><p>Cooked dishes +5, favourites +3, ratings +1–5, votes +2. Skips reduce the score. Allergies belong in ingredient exclusions, which are hard rules.</p></div></div>`;}
function renderInsights(){const s=state(),hist=s.history,cuisines={};hist.forEach(h=>{if(h.cuisine)cuisines[h.cuisine]=(cuisines[h.cuisine]||0)+1;});return heading('YOUR KITCHEN, OVER TIME','Small habits. Good things.','Insights from your own cooking history.')+`<div class="metrics">${[[hist.length,'Meals remembered'],[s.favorites.length,'Favourite dishes'],[s.combos.length,'Saved combinations'],[new Set(hist.flatMap(h=>h.dishIds||[])).size,'Different dishes cooked']].map(([n,l])=>`<article class="metric"><b>${n}</b><span>${l}</span></article>`).join('')}</div><div class="two-columns"><section class="panel"><h2>Favourite cuisines</h2>${Object.entries(cuisines).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<div class="rank-row"><b>${esc(c)}</b><span>${n} meals</span></div>`).join('')||'<p>Your cooking history will tell this story.</p>'}</section><section class="panel"><h2>Favourite dishes</h2>${s.favorites.map(id=>`<div class="rank-row"><button class="text-btn" data-action="recipe" data-id="${esc(id)}">${esc(dishes.get(id)?.name||id.replaceAll('-',' '))}</button><span>♥</span></div>`).join('')||'<p>Tap the heart on a dish to keep it close.</p>'}</section></div><p class="quiet-note">Use Record consumption to track food used or wasted. Serving estimates appear after three portion records for the same dish.</p>`;}
function renderSettings(){const s=state(),p=store?.value('profile:me',{})||{};return heading('MAKE YOURSELF AT HOME','Your kitchen, your way.','Account, food rules and the little things that make it yours.')+`<div class="settings-grid"><section class="panel"><h2>Account & profile</h2>${user?`<p>${esc(user.email)}</p><form id="profileForm"><label>Display name<input name="name" value="${esc(p.name||'')}" maxlength="60"></label><label>Cooking experience<select name="skill">${opts(['Beginner','Regular Cook','Advanced','Professional'],p.skill||'Regular Cook')}</select></label><button class="primary small">Save profile</button></form><div class="button-row"><button class="text-btn" data-action="export">Export my kitchen</button><button class="text-btn" data-action="signout">Sign out</button></div><button class="text-btn danger-text" data-action="delete-account">Delete account</button>`:'<p>A private kitchen that follows you from device to device.</p><button class="primary" data-action="auth">Sign in or create an account</button>'}</section><section class="panel"><h2>Food rules</h2><p>Pure vegetarian. Always eggless.</p><label class="check-row"><input type="checkbox" data-household-jain ${filters.jain?'checked':''}> Strict Jain household</label><p>Your diet rules are remembered for future visits.</p><div class="tags">${s.exclusions.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>No additional exclusions</span>'}</div><button class="secondary" data-action="exclusions">Edit exclusions</button><h3>Hidden dishes</h3>${s.hidden.length?s.hidden.map(id=>`<div class="rank-row"><span>${esc(dishes.get(id)?.name||id.replaceAll('-',' '))}</span><button class="text-btn" data-action="restore" data-id="${esc(id)}">Restore</button></div>`).join(''):'<p>No hidden dishes.</p>'}</section><section class="panel"><h2>Comfort & accessibility</h2><label class="check-row"><input type="checkbox" data-metric-units ${household.metric?'checked':''}> Show grams and millilitres</label><label class="check-row"><input type="checkbox" id="largeText" ${document.body.classList.contains('large-text')?'checked':''}> Larger text</label><label class="check-row"><input type="checkbox" id="highContrast" ${document.body.classList.contains('high-contrast')?'checked':''}> High contrast</label><label class="check-row"><input type="checkbox" id="reducedMotion" ${document.body.classList.contains('reduced-motion')?'checked':''}> Reduce motion</label><button class="secondary" data-action="install">Install app (optional)</button><p class="muted">Choose English, Gujarati or Hindi from the language menu at any time. Your choice is saved on this device.</p></section><section class="panel"><h2>Kitchen preferences</h2><label>Kitchen experience<select id="kitchenExperience">${opts([['home','Home Kitchen'],['factory','Canteen']],party.mode==='home'?'home':'factory')}</select></label><button class="secondary" data-action="headcount">${esc(MODES[party.mode])} · Change</button><button class="secondary" data-action="equipment">Equipment</button><h3>Weather mood</h3><div class="button-row">${['hot','rainy','cool','pleasant'].map(w=>`<button class="chip" data-action="weather" data-value="${w}">${w}</button>`).join('')}</div><button class="text-btn" data-action="location">Use my location</button><p class="muted">Location is requested only when you choose it. You can always select weather manually.</p></section></div>${syncState.conflicts?`<section class="panel"><h2>Edits need your choice</h2><p>The same item changed on another device.</p>${[...store.conflicts].map(id=>`<div class="rank-row"><span>${esc(id)}</span><button data-action="conflict-local" data-id="${esc(id)}">Keep this device</button><button data-action="conflict-cloud" data-id="${esc(id)}">Use cloud version</button></div>`).join('')}</section>`:''}<footer class="settings-footer"><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/delete-account">Account deletion</a><span>Version ${VERSION}</span></footer>`;}
function renderGroceryLoading(){return heading('ONE LIST, LESS GUESSWORK','Let’s stock the week.','Combined quantities from your calendar, grouped for an easier shop.',`<button class="secondary" data-nav="planner">← Back to my week</button>`)+`<div id="groceryContent" aria-live="polite"><p>Gathering your ingredients…</p></div>`;}
async function fillGrocery(){try{const s=state(),plans=s.plans.filter(p=>p.date>=week&&p.date<=addDays(week,6)),scaled=[];let outlines=0;for(const p of plans)for(const id of p.dishIds||[]){const r=await recipeFor(id);if(r.status!=='complete'){outlines++;continue;}scaled.push(scaleRecipe(r,p.party||party));}const items=shoppingList(scaled,s.pantry);if(currentView!=='grocery')return;const groups={};items.forEach(i=>(groups[i.group]??=[]).push(i));$('#groceryContent').innerHTML=`<div class="grocery-summary"><b>${items.length} combined ingredients</b><span>${plans.length} planned meals</span><button class="text-btn" data-action="grocery-copy">Copy list</button></div>${outlines?`<p class="notice">${outlines} recipe outlines have been excluded from shopping quantities. Add complete recipes to get reliable ingredient lists.</p>`:''}<div class="grocery-grid">${Object.entries(groups).map(([name,rows])=>`<section class="panel"><h2>${name}</h2>${rows.map(i=>`<label class="grocery-row"><input type="checkbox" data-grocery="${esc(week+':'+i.key)}" ${store?.value('grocery:'+week+':'+i.key)?.checked?'checked':''}><span>${esc(i.name)}${i.onHand?`<small>Need ${displayQuantity({...i,qty:i.required})} · In pantry ${displayQuantity({...i,qty:i.onHand})}</small>`:''}</span><b>${displayQuantity(i)}</b></label>`).join('')}</section>`).join('')||empty('Your list starts with your plan.','Choose complete recipes for the week to combine ingredient quantities.','planner','Open my week')}</div>`;fillGrocery.items=items;}catch(e){if($('#groceryContent'))$('#groceryContent').textContent=e.message;}}

function headcountDialog(after,force=false){
 if(after&&household.confirmed&&!force)return after();
 const home=party.mode==='home';
 modal(home?'Your household':'Your kitchen size',`<p>Save your usual numbers once. You can change them anytime from your kitchen settings.</p><form id="partyForm"><div class="form-grid"><label>${home?'Adults':'People'}<input name="adults" type="number" min="0" max="100000" required value="${party.adults}"></label><label>Kids<input name="kids" type="number" min="0" max="100000" required value="${party.kids}"></label><label>Additional guests<input name="guests" type="number" min="0" max="100000" value="${party.guests||0}"></label><label>Ingredient budget ₹ / person<input name="budget" type="number" min="0" max="100000" value="${party.budget||100}"></label>${home?'':`<label>Jain meals (part of total)<input name="jainMeals" type="number" min="0" max="100000" value="${party.jainMeals||0}"></label><label>Attendance buffer %<input name="buffer" type="number" min="0" max="50" value="${party.buffer||0}"></label>`}</div>${home?'':`<details><summary>Event & service details</summary><label>Event type<select name="eventType">${opts(['Wedding','Reception','Birthday','Corporate event','Festival','Custom'],party.eventType)}</select></label><label>Meal<select name="meal">${opts(['Breakfast','Lunch','High Tea','Dinner','All-day menu'],party.meal)}</select></label><label>Service<select name="service">${opts(['Buffet','Sit-down','Live counters','Mixed'],party.service)}</select></label></details>`}<label class="check-row"><input type="checkbox" name="householdJain" ${filters.jain?'checked':''}> Strict Jain household</label><p>Children count as 0.6 adult portions for ingredient estimates.</p><button class="primary wide">Save & continue →</button></form>`);saveCallback=after;
}

async function runSearch(){await saveHousehold();const ticket=++searchVersion;notify('Finding your next good meal…');const items=await loadCategory(filters.category);if(ticket!==searchVersion)return;const custom=customDishes();custom.forEach(d=>dishes.set(d.id,d));results=recommend([...items,...custom],currentFilters(),state(),Infinity);searchCompleted=true;visible=12;nav('discover');if(!results.length)notify('No eligible matches. Your hard food rules have been preserved.');}
function customDishes(){return state().custom.map(r=>({id:r.id||r._id.slice(7),canonicalId:r.id||r._id.slice(7),name:r.name,cuisine:r.cuisine||'Family recipe',categories:r.categories||[r.category||'Dinner'],ingredients:r.ingredients?.map?.(x=>typeof x==='string'?x:x.name)||r.majorIngredients||[],method:r.method||'curry',time:r.time||30,effort:r.effort||'medium',vegetarian:r.vegetarian===true,eggless:r.eggless===true,ingredientsComplete:r.status==='complete',jainVerified:r.jainVerified===true,kids:r.kids===true,nutrition:r.nutrition||['balanced'],recipeStatus:r.status||'outline',bulkScore:5,equipment:[],allergens:[],custom:true}));}
async function recipeFor(id){const cid=canonical(id),custom=state().custom.find(x=>x.id===cid||x._id==='recipe:'+cid);if(custom)return {...custom,status:custom.status||'outline',ingredients:(custom.ingredients||[]).filter(x=>typeof x==='object'),steps:custom.steps||custom.instructions?.split('\n').filter(Boolean)||['This imported family dish has no saved method yet. Edit it in the recipe vault.'],tips:[custom.notes||''],baseServings:custom.baseServings||4};return getRecipe(cid);}
async function openRecipe(id){const epoch=authEpoch,r=await recipeFor(id);if(epoch!==authEpoch)return;activeRecipe=r;recipeParty={...party};step=0;showRecipe();}
function showRecipe(){const r=activeRecipe,scaled=scaleRecipe(r,recipeParty),d=dishes.get(r.id),h=scaled;modal(r.name,`<div class="recipe-banner">${r.privatePhoto?`<img class="food-photo" src="${esc(r.privatePhoto)}" alt="${esc(r.name)} — private family recipe">`:dishPhoto(d||r,true)}<div><span class="badge">${r.status==='complete'?'Complete recipe':'Preparation outline'}</span><p>Pure vegetarian · Eggless · Base recipe for ${r.baseServings||4}</p></div></div>${photoCredit(d||r)}${r.passiveTime?`<p class="quiet-note">${esc(r.passiveTime)}</p>`:""}${r.status!=='complete'?'<p class="notice">This is an incomplete preparation outline inherited from the earlier catalogue. Its provisional quantities are excluded from grocery and cost totals.</p>':''}<form id="recipeScaleForm" class="form-grid"><label>Adults<input type="number" name="adults" min="0" max="100000" value="${recipeParty.adults}" required></label><label>Kids<input type="number" name="kids" min="0" max="100000" value="${recipeParty.kids}" required></label><label>Guests<input type="number" name="guests" min="0" max="100000" value="${recipeParty.guests||0}"></label>${party.mode==='home'?'':`<label>Buffer %<input type="number" name="buffer" min="0" max="50" value="${recipeParty.buffer||0}"></label>`}<button class="secondary">Update quantities</button></form><div class="recipe-stats"><b>${h.servings} servings</b><span>${h.equivalent.toFixed(1)} adult portions</span>${r.status==='complete'?`<span>Ingredient estimate ${currency(h.cost)}${h.missingPrices.length?' + unpriced items':''}</span>`:''}</div><div class="recipe-columns"><section><h3>Ingredients</h3><label class="check-row"><input type="checkbox" data-metric-units ${household.metric?'checked':''}> Show grams and millilitres</label><p class="quiet-note">Household measures are approximate. 1 cup = 240 ml; 1 tbsp = 15 ml; 1 tsp = 5 ml. Ingredients without a reliable conversion keep their weight.</p>${h.ingredients.map(i=>`<div class="ingredient-row"><span>${esc(i.name)}</span><b>${displayQuantity(i)}</b></div>`).join('')}</section><section><h3>How it comes together</h3><p class="quiet-note">Method quantities refer to the base recipe. When changing servings, use the adjusted ingredient list and divide quantities between steps in the same proportions.</p><ol class="steps">${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section></div><p class="quiet-note">${esc(h.planningNote||r.notes||'')}</p><details><summary>Tips & substitutions</summary>${[...(r.tips||[]),...(r.substitutions||[])].map(t=>`<p>${esc(t)}</p>`).join('')}</details>${d?.nutrition?`<div class="tags">${d.nutrition.map(n=>`<span>${esc(n.replaceAll('-',' '))}</span>`).join('')}</div>`:''}<div class="button-row"><button class="primary" data-action="start-cooking">Start cooking →</button><button class="secondary" data-action="basket" data-id="${esc(r.id)}">Add to menu</button><button class="text-btn" data-action="cook" data-id="${esc(r.id)}">Mark cooked</button></div>`);}
function showCooking(){const r=activeRecipe;modal('A little focus. Something delicious.',`<div class="cooking-progress"><span>Step ${step+1} of ${r.steps.length}</span><progress value="${step+1}" max="${r.steps.length}"></progress></div><h3 class="cooking-dish">${esc(r.name)}</h3><p class="cooking-step">${esc(skillStep(r.steps[step],store?.value('profile:me',{})?.skill))}</p><div class="button-row"><button class="secondary" data-action="step-prev" ${step===0?'disabled':''}>← Previous</button><button class="text-btn" data-action="step-repeat">Repeat step</button><button class="primary" data-action="step-next">${step===r.steps.length-1?'Finish cooking ✓':'Next step →'}</button></div><form id="timerForm" class="timer-form"><label>Timer name<input name="name" placeholder="Rice" maxlength="30" required></label><label>Minutes<input name="minutes" type="number" min="1" max="240" value="8" required></label><button class="secondary">Set timer</button></form><div id="timerList" aria-live="polite"></div><button class="text-btn" data-action="troubleshoot">Need a little help?</button>`);drawTimers();}
function drawTimers(){if(!$('#timerList'))return;$('#timerList').innerHTML=timers.map(t=>{const secs=Math.max(0,Math.ceil((t.end-Date.now())/1000));return `<div class="rank-row"><b>${esc(t.name)}</b><span>${secs?Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0'):'Ready ✓'}</span><button class="text-btn" data-action="timer-remove" data-id="${t.id}" aria-label="Remove timer ${esc(t.name)}">×</button></div>`;}).join('');}
setInterval(()=>{timers.forEach(t=>{if(!t.done&&t.end<=Date.now()){t.done=true;notify(t.name+' timer is ready.');}});drawTimers();},1000);

function comboEditor(combo){if(!requireUser())return;const c=combo||{name:'',dishIds:[...basket],party:{...party},notes:'',tags:[]};modal(c._id?'Edit your menu':'Give this meal a home',`<form id="comboForm"><input type="hidden" name="id" value="${esc(c._id||'')}"><label>Menu name<input name="name" required maxlength="100" value="${esc(c.name)}" placeholder="My Saturday dinner"></label><div class="form-grid"><label>Cuisine<input name="cuisine" maxlength="60" value="${esc(c.cuisine||'')}" placeholder="Rajasthani"></label><label>Occasion<input name="occasion" maxlength="60" value="${esc(c.occasion||'')}" placeholder="Sunday lunch"></label></div><label>Dishes<select name="dishIds" multiple size="8" required>${[...dishes.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(d=>`<option value="${esc(d.id)}" ${(c.dishIds||[]).map(canonical).includes(d.id)?'selected':''}>${esc(d.name)}</option>`).join('')}</select><small>Use Ctrl / Command to select more than one, or build your selection with “Add to menu” on dish cards.</small></label><label>Notes<textarea name="notes" rows="3" maxlength="2000">${esc(c.notes||'')}</textarea></label><label>Tags, separated by commas<input name="tags" maxlength="200" value="${esc(c.tags?.join(', ')||'')}"></label><label class="check-row"><input type="checkbox" name="favorite" ${c.favorite?'checked':''}> Favourite menu</label><p>Saved for ${headcount(c.party||party).servings} servings · ${esc(MODES[(c.party||party).mode])}. Your saved household size is used when you reuse it.</p><button class="primary wide">Save combination</button></form>`);comboEditor.current=c;}
async function reuseMenu(menu){const ids=(menu.dishIds||[menu.dishId]).filter(Boolean).map(canonical);await loadCategories(['Lunch','Breakfast','Snacks','Desserts','Salads','Breads','Cold Drinks']);headcountDialog(async()=>{const rejected=ids.filter(id=>{const d=dishes.get(id);return !d||!eligible(d,currentFilters(),state());});if(rejected.length){notify('Some dishes are locked, hidden or conflict with your food rules. Review the menu before reusing it.');basket=ids.filter(id=>!rejected.includes(id));}else basket=ids;openBasket();});}
async function openBasket(){
 const list=basket.map(id=>dishes.get(id)).filter(Boolean);let cost=0,complete=0,missingPrices=0;for(const d of list){const r=await recipeFor(d.id);if(r.status==='complete'){const scaled=scaleRecipe(r,party);cost+=scaled.cost;missingPrices+=scaled.missingPrices.length;complete++;}}
 const h=headcount(party),production=productionPlan(list,party);
 modal('A menu that comes together',`<p>${party.mode==='home'?`${h.servings} servings`:`${h.total} people + ${h.buffer}% buffer = <b>${h.servings} servings</b>`}</p>${list.length?list.map(d=>`<div class="basket-row"><span>${emoji(d)}</span><div><b>${esc(d.name)}</b><small>${esc(d.cuisine)}${party.mode==='home'?'':` · ${scaleSuitability(d,h.servings,party.mode)}/10 scale suitability`}</small></div><button class="text-btn" data-action="basket-remove" data-id="${esc(d.id)}" aria-label="Remove ${esc(d.name)}">×</button></div>`).join(''):'<p>Your menu is waiting for its first dish. Add something from Discover.</p>'}<div class="cost-panel"><span>Ingredient subtotal${complete<list.length||missingPrices?' (incomplete)':''}</span><b>${currency(cost)}</b><p>${currency(cost/h.total)} / person${party.mode==='home'?'':` · ${currency(cost-cost/(1+h.buffer/100))} buffer cost`}</p><small>${complete} of ${list.length} dishes have complete recipes. Sample rates; labour, energy, service and unpriced items excluded.</small></div>${party.budget&&cost/h.total>party.budget?'<p class="notice">This ingredient subtotal is above your per-person budget.</p>':''}${party.mode!=='home'?`<details><summary>Production & staffing guidance</summary><p>${esc(production.note)}</p><div class="tags">${Object.entries(production.staff).map(([k,v])=>`<span>${k}: ${v}</span>`).join('')}</div>${production.timeline.map(x=>`<p><b>${x.when}</b><br>${esc(x.task)}</p>`).join('')}</details>`:''}<div class="button-row"><button class="primary" data-action="combo-new" ${list.length?'':'disabled'}>Save combo</button><button class="secondary" data-action="basket-plan" ${list.length?'':'disabled'}>Add to calendar</button><button class="text-btn" data-action="basket-cook" ${list.length?'':'disabled'}>Mark cooked</button></div>`);openBasket.cost=cost;
}
function planDialog(ids=basket){if(!requireUser())return;if(!ids.length)return notify('Add a dish to your menu first.');modal('Find a place in your week',`<form id="planForm"><label>Date<input type="date" name="date" required value="${planTarget?.date||dayKey()}"></label><label>Meal<select name="meal">${opts(MEALS,planTarget?.meal||'Dinner')}</select></label><label>Menu name<input name="name" value="${esc(ids.map(id=>dishes.get(id)?.name||id).join(' + '))}" maxlength="200" required></label><label class="check-row"><input type="checkbox" name="repeat"> Repeat on this weekday (manage in Recurring menus)</label><button class="primary wide">Save to calendar</button></form>`);planDialog.ids=[...ids];}
async function savePlan(date,meal,ids,name){
 const mapped=ids.map(canonical),s=state();const planningHistory=[...s.history,...s.plans.filter(p=>!(p.date===date&&p.meal===meal)).map(p=>({...p,planned:true,date:p.date+'T12:00:00'}))];
 const unsafe=mapped.filter(id=>{const d=dishes.get(id);return !d||!eligible(d,currentFilters(),{...s,history:planningHistory},new Date(date+'T23:59:59').getTime());});
 if(unsafe.length)throw Error('This meal includes a locked, hidden, unavailable or excluded dish. Choose another dish or a later date.');
 return put('plan','plan:'+date+':'+meal,{date,meal,name,dishIds:mapped,canonicalIds:mapped.map(id=>dishes.get(id)?.canonicalId||id),party:{...party}});
}
function stockDialog(kind){if(!requireUser())return;modal(kind==='leftover'?'Give leftovers a plan':'What’s in your kitchen?',`<form id="stockForm"><input type="hidden" name="kind" value="${kind}"><label>${kind==='leftover'?'Leftover':'Ingredient'}<input name="name" required maxlength="100" placeholder="${kind==='leftover'?'Cooked rice':'Paneer'}"></label><label>Quantity<input name="quantity" maxlength="60" placeholder="e.g. 300 g"></label><label>${kind==='leftover'?'Use-by date':'Best-before date'}<input name="expiry" type="date"></label><button class="primary wide">Add to kitchen</button></form>`);}
function familyDialog(member){if(!requireUser())return;const p=member||{};modal('Everyone gets a seat',`<form id="familyForm"><input name="id" type="hidden" value="${esc(p._id||'')}"><label>Name<input name="name" required maxlength="60" value="${esc(p.name||'')}" placeholder="Mom, Papa, Ayaan…"></label><label class="check-row"><input type="checkbox" name="child" ${p.child?'checked':''}> Child profile</label><div class="form-grid"><label>Likes (ingredients)<input name="likes" maxlength="300" value="${esc(p.likes?.join(', ')||'')}" placeholder="paneer, peas"></label><label>Dislikes<input name="dislikes" maxlength="300" value="${esc(p.dislikes?.join(', ')||'')}" placeholder="bitter gourd"></label><label>Spice tolerance<select name="spice">${opts(['Mild','Medium','Spicy'],p.spice||'Mild')}</select></label><label>Favourite cuisines<input name="cuisines" maxlength="300" value="${esc(p.cuisines?.join(', ')||'')}"></label></div><label>Diet preferences<input name="diet" maxlength="300" value="${esc(p.diet||'Vegetarian, eggless')}"></label><p class="quiet-note">For allergies, also add the ingredient to Settings → Exclusions.</p><button class="primary wide">Save member</button></form>`);}
function voteDialog(id){if(!requireUser())return;const members=state().family,values=state().votes[id]||{};modal('What does your table think?',members.length?`<h3>${esc(dishes.get(id)?.name||id)}</h3><form id="voteForm"><input type="hidden" name="dishId" value="${esc(id)}">${members.map(m=>`<label>${esc(m.name)}<select name="${esc(m._id)}">${opts([[0,'No vote yet'],[1,'Yes, please!'],[-1,'Maybe another day']],values[m._id]||0)}</select></label>`).join('')}<button class="primary wide">Save family votes</button></form>`:'<p>Add your family members first so each person gets one vote per dish.</p><button class="primary" data-action="family-add">Add a member</button>');}
function customDialog(recipe){if(!requireUser())return;const r=recipe||{};modal('Your family recipe vault',`<p>Private to your account. Keep the recipe and the story behind it.</p><form id="customForm"><input name="id" type="hidden" value="${esc(r._id||'')}"><label>Recipe title<input name="name" maxlength="100" required value="${esc(r.name||'')}" placeholder="Nani’s gatte ki sabzi"></label><div class="form-grid"><label>Family member<input name="author" maxlength="60" value="${esc(r.author||'')}"></label><label>Cuisine<input name="cuisine" maxlength="60" value="${esc(r.cuisine||'Family recipe')}"></label><label>Category<select name="category">${opts(CATEGORIES,r.categories?.[0]||r.category||'Dinner')}</select></label><label>Time, minutes<input name="time" type="number" min="5" max="1440" required value="${r.time||30}"></label></div><label>Ingredients for 4 adults (one per line: name, quantity, unit)<textarea name="ingredients" required rows="5" maxlength="8000" placeholder="gram flour, 200, g&#10;curd, 300, g">${esc(r.ingredients?.filter?.(i=>typeof i==='object').map(i=>`${i.name}, ${i.qty}, ${i.unit}`).join('\n')||'')}</textarea></label><label>Steps (one per line)<textarea name="steps" rows="5" maxlength="12000" required>${esc(r.steps?.join('\n')||'')}</textarea></label><label>Family story & notes<textarea name="notes" rows="3" maxlength="3000">${esc(r.notes||'')}</textarea></label><label class="check-row"><input type="checkbox" name="foodConfirmed" required> I have listed all ingredients, including sauces and seasonings, and checked that every ingredient is vegetarian and eggless.</label><button class="primary wide">Save private recipe</button></form>`);}
function cookDialog(ids,name){if(!requireUser())return;modal('A meal worth remembering',`<form id="cookedForm"><h3>${esc(name)}</h3><label>Rating<select name="rating">${opts([[5,'5 · Loved it'],[4,'4 · Really good'],[3,'3 · Good'],[2,'2 · Could be better'],[1,'1 · Not for us']],4)}</select></label><label>Comments<textarea name="comments" maxlength="1000" rows="3"></textarea></label><p>Main dishes will rest for 8 days. Common sides remain available.</p><button class="primary wide">Save to meal memory</button></form>`);cookDialog.ids=ids;cookDialog.name=name;}
function updateSync(){const el=$('#syncStatus');if(!el)return;el.textContent=!user?'Your kitchen, kept private':syncState.error?'Sync needs attention':syncState.conflicts?'Edits need your choice':!navigator.onLine?'Offline · saved on this device':syncState.dirty?`${syncState.dirty} changes waiting to sync`:'Kitchen synced';el.classList.toggle('sync-error',!!syncState.error||!!syncState.conflicts);el.title=syncState.error||'';}
function showAuth(){const signup=authMode==='signup',forgot=authMode==='forgot',recovery=authMode==='recovery';modal(recovery?'A fresh start':signup?'Make this kitchen yours':forgot?'Forgot your password?':'Welcome to your kitchen',`<p>${signup?'One account. Your private kitchen, everywhere.':forgot?'We’ll send a password reset link to your email.':'Good food starts with feeling at home.'}</p><form id="authForm">${recovery?'':`<label>Email<input type="email" name="email" required autocomplete="email" maxlength="254"></label>`}${forgot?'':`<label>Password<input type="password" name="password" minlength="${signup||recovery?10:6}" maxlength="128" required autocomplete="${signup||recovery?'new-password':'current-password'}"></label>`}${recovery?'<label>Repeat password<input type="password" name="confirm" required minlength="10" autocomplete="new-password"></label>':''}${signup?'<p class="quiet-note">Creating an account means you accept our <a href="/terms" target="_blank" rel="noopener">Terms</a> and <a href="/privacy" target="_blank" rel="noopener">Privacy notice</a>.</p>':''}<div id="authError" class="form-error" role="alert"></div><button class="primary wide">${signup?'Create account':forgot?'Send reset link':recovery?'Save new password':'Sign in'}</button></form><div class="auth-links"><button class="text-btn" data-action="auth-mode" data-mode="${signup||forgot?'login':'signup'}">${signup||forgot?'Back to sign in':'Create an account'}</button>${!forgot&&!recovery?'<button class="text-btn" data-action="auth-mode" data-mode="forgot">Forgot password?</button>':''}</div><button class="text-btn" data-action="close">Keep exploring as a guest →</button>`);}
async function initAuth(){
 try{config=await cachedJSON('/api/config');if(!config.configured)throw Error(config.message);
  const {createClient}=await import('./auth-client.js');
  client=await createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'kavita-kitchen-auth-v2'}});
  client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{if(event==='PASSWORD_RECOVERY'){authMode='recovery';showAuth();}else if(event==='SIGNED_OUT')activateUser(null);else if(session?.user&&(event==='SIGNED_IN'||event==='INITIAL_SESSION'))activateUser(session.user);},0);});
  const {data,error:e}=await client.auth.getSession();if(e)throw e;if(data.session?.user)await activateUser(data.session.user);
 }catch(e){config={configured:false,message:e.message};updateSync();}
}
async function activateUser(next){
 if(next?.id===user?.id)return;features?.reset();
 const epoch=++authEpoch;store?.close();store=null;user=next;syncState={};household=readHousehold(localStorage,next?.id,defaults);party=household.party;basket=[];results=[];searchCompleted=false;explicitFilters.clear();activeRecipe=null;timers=[];filters={category:'Dinner',cuisine:'Any',time:0,effort:'',jain:household.jain,query:''};for(const [id,d] of dishes)if(d.custom)dishes.delete(id);close();$('#dialogBody').replaceChildren();render();
 if(!next)return;
 const opened=await new KitchenStore(next.id,supabaseRemote(client,next.id,config),s=>{if(epoch!==authEpoch)return;syncState=s;updateSync();}).open();
 if(epoch!==authEpoch){opened.close();return;}store=opened;
 const saved=store.value('config:party');if(saved){try{headcount({...defaults,...saved});party={...defaults,...saved};household.confirmed=true;}catch{}}
 const diet=store.value('config:household');if(diet){household={...household,...diet};filters.jain=!!diet.jain;}else if(party.jainMeals>0)filters.jain=true;
 store.onChange=()=>{if(epoch!==authEpoch)return;const diet=store.value('config:household');if(diet){household={...household,...diet};filters.jain=!!diet.jain;}const p=store.value('config:party');if(p){try{headcount({...defaults,...p});party={...defaults,...p};}catch{}}render();};render();
 const {error:e}=await client.rpc('kkk_import_legacy');if(epoch!==authEpoch)return;
 if(e){syncState={error:'Database migration needed. Changes remain private on this device.'};updateSync();notify(syncState.error);return;}
 await store.sync();
}
async function submitAuth(form){
 if(!client)throw Error('Account services are unavailable. The existing Supabase connection must be configured.');
 const f=new FormData(form),email=String(f.get('email')||'').trim(),password=String(f.get('password')||'');
 const mode=authMode;let result;
 if(mode==='signup')result=await client.auth.signUp({email,password,options:{emailRedirectTo:location.origin}});
 else if(mode==='forgot')result=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin});
 else if(mode==='recovery'){if(password!==f.get('confirm'))throw Error('Passwords do not match.');result=await client.auth.updateUser({password});}
 else result=await client.auth.signInWithPassword({email,password});
 if(result.error)throw result.error;
 if(mode==='signup'&&!result.data?.session){$('#authError').textContent='Check your email to confirm your account, then sign in.';return;}
 if(mode==='forgot'){$('#authError').textContent='If this email belongs to an account, a reset link will be sent.';return;}
 if(mode==='recovery'){close();notify('Password updated.');return;}
 if(result.data?.user)await activateUser(result.data.user);close();notify('Welcome to your kitchen.');
}
function deletionDialog(){if(!requireUser())return;modal('Delete your account',`<p>This permanently removes your account, saved plans, kitchen history and private recipes. Export a copy first if you want to keep them.</p><p>For protection, sign in again within 10 minutes before deleting.</p><form id="deleteForm"><label>Type DELETE to confirm<input name="confirmation" required pattern="DELETE" autocomplete="off"></label><div id="deleteError" class="form-error" role="alert"></div><button class="danger wide">Permanently delete account</button></form>`);}
function renderDeletionPage(){return heading('ACCOUNT CONTROL','Your kitchen belongs to you.','You can permanently delete your account and private kitchen data.')+`<section class="panel prose"><h2>Delete through the app</h2><p>Sign in, open Settings → Account → Delete account, and type DELETE. You may be asked to sign in again to confirm your identity.</p><p>This removes the Supabase Auth account and associated kitchen records, including the old cloud backup. Database backups may remain for the service provider’s configured retention period.</p><button class="danger" data-action="delete-account">Delete my account</button><p>If deletion is temporarily unavailable, the site operator must enable the server-side deletion service. Do not send passwords or secret keys.</p></section>`;}
function renderPrivacy(){return heading('PRIVACY','A private place for your kitchen.','Last updated 13 September 2026')+`<article class="panel prose"><p>We store the email address used for your account and the kitchen information you choose to save: preferences, family profiles, recipes, menus, pantry, votes and cooking history.</p><p>Supabase provides authentication and cloud storage. Vercel hosts the website. Your private kitchen records are associated with your account. Public recipe data is shared; your family recipes are not published automatically.</p><p>Account-specific data is cached in this browser for offline use and synced when it reconnects while you are signed in. Signing out removes it from the screen; the account-specific offline copy remains for your next sign-in. Use your browser’s site-data controls to remove it from a shared device.</p><p>Location is optional and requested only when you choose weather suggestions. Coordinates are sent through this site’s weather endpoint to Open-Meteo to retrieve a forecast. Use manual weather if you prefer.</p><p>No advertising trackers are included. Optional AI assistance sends only the text or photo you explicitly submit to OpenAI. AI response storage is disabled; provider processing policies still apply. Voice recognition uses your browser’s service only after you start the microphone. Sharing a menu through your device shares only the content you choose.</p><p>Export your kitchen from Settings or use <a href="/delete-account">account deletion</a>. Live backup retention, operator contact and jurisdiction-specific policy details must be completed by the operator before a public launch.</p></article>`;}
function renderTerms(){return heading('TERMS','A little clarity, before cooking.','Last updated 13 September 2026')+`<article class="panel prose"><p>Kavita ka Kitchen provides vegetarian meal-planning tools. You are responsible for checking actual ingredient labels, dietary suitability, freshness, cooking methods and equipment instructions.</p><p>Recipes include measured ingredients and step-by-step methods. Cooking times are estimates; follow the doneness checks in each recipe. Ingredient prices, staffing, serving yields and bulk timelines are planning estimates. Validate them with your kitchen team before purchasing or preparing large quantities.</p><p>Nutrition labels describe general meal characteristics and are not medical advice. Availability and online sync depend on the connected services. Keep exports of important personal recipes.</p><p>Only add content you have the right to use. Your private recipes stay private unless you explicitly share them.</p><p>The operator must complete legal entity, contact, applicable law and any paid-service terms before public launch. This release does not process payments.</p></article>`;}

async function action(name,el){
 const id=el?.dataset.id,s=state();
 if(navs[name])return nav(name);
 if(name==='close')return close();
 if(name==='auth'){authMode='login';return showAuth();}
 if(name==='auth-mode'){authMode=el.dataset.mode;return showAuth();}
 if(name==='headcount')return headcountDialog(()=>render(),true);
 if(name==='search')return headcountDialog(runSearch);
 if(name==='quick'){filters.category=el.dataset.value;if(filters.category==='Quick Meals')filters.time=30;return headcountDialog(runSearch);}
 if(name==='today-meal'){filters.category=el.dataset.value;const p=s.plans.find(x=>x.date===dayKey()&&x.meal===filters.category);if(p){basket=p.dishIds.map(canonical);await loadCategories(['Lunch','Breakfast','Breads','Salads']);return openBasket();}return headcountDialog(runSearch);}
 if(name==='surprise')return headcountDialog(async()=>{await runSearch();if(results.length)await openRecipe(results[Math.floor(Math.random()*results.length)].id);});
 if(name==='more'){visible+=12;const y=scrollY;render();window.scrollTo(0,y);return;}
 if(name==='recipe')return openRecipe(id);
 if(name==='dish-more'){const d=dishes.get(id);return modal(d.name,`<div class="menu-actions"><button data-action="recipe" data-id="${id}">Open recipe</button><button data-action="vote" data-id="${id}">Family vote</button><button data-action="single-plan" data-id="${id}">Add to calendar</button><button data-action="cook" data-id="${id}">Mark cooked & rate</button><button data-action="skip" data-id="${id}">Not interested today</button><button data-action="hide" data-id="${id}">Hide this dish</button>${d.custom?`<button data-action="custom-edit" data-id="${id}">Edit family recipe</button>`:''}</div>`);}
 if(name==='favorite'){if(!requireUser())return;const old=store.get('favorite').find(x=>canonical(x.dishId)===id);if(old)await store.remove(old._id);else await put('favorite','favorite:'+id,{dishId:id});render();return;}
 if(name==='hide'){if(!await put('hidden','hidden:'+id,{dishId:id}))return;results=results.filter(d=>d.id!==id);close();render();notify('Dish hidden. Restore it in Settings.');return;}
 if(name==='restore'){for(const row of store.get('hidden').filter(x=>canonical(x.dishId)===id))await store.remove(row._id);render();return;}
 if(name==='skip'){const p=s.preferences[id]||{};if(!await put('preference','preference:'+id,{dishId:id,value:{...p,skipped:(p.skipped||0)+1}}))return;results=results.filter(d=>d.id!==id);close();render();return;}
 if(name==='basket'){if(!basket.includes(id))basket.push(id);notify('Added to your menu.');if(!$('#dialog').open)render();return;}
 if(name==='basket-remove'){basket=basket.filter(x=>x!==id);return openBasket();}
 if(name==='basket-open')return openBasket();
 if(name==='basket-plan')return planDialog();
 if(name==='single-plan')return headcountDialog(()=>planDialog([id]));
 if(name==='basket-cook')return cookDialog([...basket],basket.map(x=>dishes.get(x)?.name||x).join(' + '));
 if(name==='cook')return cookDialog([id],dishes.get(id)?.name||activeRecipe?.name||id);
 if(name==='combo-new'){if(!requireUser())return;await loadCategories(['Lunch','Breakfast','Snacks','Desserts','Breads','Salads','Cold Drinks']);return comboEditor();}
 if(name==='combo-edit')return comboEditor(s.combos.find(x=>x._id===id));
 if(name==='combo-reuse')return reuseMenu(s.combos.find(x=>x._id===id));
 if(name==='history-reuse')return reuseMenu(s.history.find(x=>x._id===id));
 if(name==='combo-more'){const c=s.combos.find(x=>x._id===id);return modal(c.name,`<div class="menu-actions"><button data-action="combo-duplicate" data-id="${esc(id)}">Duplicate menu</button><button data-action="combo-share" data-id="${esc(id)}">Share meal card</button><button class="danger-text" data-action="combo-delete" data-id="${esc(id)}">Delete saved menu</button></div>`);}
 if(name==='combo-duplicate'){const c=s.combos.find(x=>x._id===id);await put('combo','combo:'+uid(),{...c,_id:undefined,name:c.name+' (copy)'});close();render();return;}
 if(name==='combo-delete'){await store.remove(id);close();render();return;}
 if(name==='combo-share'){const c=s.combos.find(x=>x._id===id);const text=c.name+'\n'+(c.dishNames||[]).map(translate).join('\n')+'\n\nMade with Kavita ka Kitchen';if(navigator.share){try{await navigator.share({title:c.name,text});}catch(e){if(e.name!=='AbortError')throw e;}}else{await navigator.clipboard.writeText(text);notify('Meal card text copied. Paste it into your favourite chat.');}return;}
 if(name==='coordinated')return headcountDialog(async()=>{const all=await loadCategories(['Mocktails','Soups','Snacks','Chaats','Sabzi/Curries','Dal/Legumes','Breads','Rice','Salads','Desserts']);const m=coordinatedMenu(all,party,currentFilters(),state());basket=m.dishes.map(d=>d.id);await openBasket();if(m.missing.length)notify('No eligible match for: '+m.missing.join(', ')+'. Dietary rules remain fixed.');});
 if(name==='world'){document.querySelector('[data-extra="map"]')?.click();if(!document.querySelector('[data-extra="map"]')){nav('discover');document.querySelector('[data-extra="map"]')?.click();}return;}
 if(name==='legacy-world'){modal('Follow your curiosity',`<p>Discover India’s regional kitchens and vegetarian ideas from around the world.</p><div class="cuisine-grid">${(manifest?.cuisines||[]).map(c=>`<button class="secondary" data-action="cuisine-search" data-value="${esc(c)}">${esc(c)} ↗</button>`).join('')}</div>`);return;}
 if(name==='cuisine-search'){filters.cuisine=el.dataset.value;filters.category='Dinner';return headcountDialog(runSearch);}
 if(name==='week-prev'){week=addDays(week,-7);render();return;}
 if(name==='week-next'){week=addDays(week,7);render();return;}
 if(name==='this-week'){week=monday();render();return;}
 if(name==='plan-week'){if(!requireUser())return;return headcountDialog(async()=>{const all=await loadCategories(MEALS),s=state(),existing=Object.fromEntries(s.plans.map(p=>[p.date+':'+p.meal,p]));const generated=planWeek(all,week,party,currentFilters(),s,existing);for(const [key,p] of Object.entries(generated.plan))if(!existing[key])await put('plan','plan:'+key,p);nav('planner');notify(generated.unfilled?`Week saved with ${generated.unfilled} open slots; food rules were preserved.`:'Your week is planned.');});}
 if(name==='copy-week'){if(!requireUser())return;await loadCategories(MEALS);let count=0,skips=0;for(const p of s.plans.filter(p=>p.date>=addDays(week,-7)&&p.date<week)){const date=addDays(p.date,7);if(s.plans.some(x=>x.date===date&&x.meal===p.meal))continue;try{await savePlan(date,p.meal,p.dishIds,p.name);count++;}catch{skips++;}}render();notify(`${count} meals copied${skips?`; ${skips} skipped to respect food rules`:''}. Existing slots were kept.`);return;}
 if(name==='slot'){if(!requireUser())return;planTarget={date:el.dataset.date,meal:el.dataset.meal};const p=s.plans.find(x=>x.date===planTarget.date&&x.meal===planTarget.meal);if(p)return modal(p.name,`<p>${esc(p.date)} · ${esc(p.meal)}</p><div class="menu-actions"><button data-action="slot-view" data-id="${esc(p._id)}">View menu & quantities</button><button data-action="slot-replace">Replace meal</button><button data-action="slot-clear" data-id="${esc(p._id)}">Clear this meal</button></div>`);return slotPicker();}
 if(name==='slot-view'){const p=s.plans.find(x=>x._id===id);party={...defaults,...p.party};basket=p.dishIds.map(canonical);await loadCategories(['Lunch','Breakfast','Snacks','Breads','Salads']);return openBasket();}
 if(name==='slot-replace')return slotPicker();
 if(name==='slot-clear'){await store.remove(id);close();render();return;}
 if(name==='slot-discover'){close();filters.category=planTarget.meal;return headcountDialog(runSearch);}
 if(name==='slot-basket')return headcountDialog(()=>planDialog());
 if(name==='slot-combo'){const c=s.combos.find(x=>x._id===id);basket=c.dishIds.map(canonical);return headcountDialog(()=>planDialog());}
 if(name==='day-menu'){const date=el.dataset.date;modal('Make this day work for you',`<p>${date}</p><div class="menu-actions"><button data-action="day-duplicate" data-date="${date}">Duplicate this day</button><button data-action="day-clear" data-date="${date}">Clear this day</button></div>`);return;}
 if(name==='day-clear'){for(const p of s.plans.filter(x=>x.date===el.dataset.date))await store.remove(p._id);close();render();return;}
 if(name==='day-duplicate'){modal('Copy a day',`<form id="duplicateDayForm"><input type="hidden" name="source" value="${el.dataset.date}"><label>Copy to date<input type="date" name="target" value="${addDays(el.dataset.date,1)}" required></label><p>Occupied slots are kept. Rotation and exclusions remain in effect.</p><button class="primary">Copy day</button></form>`);return;}
 if(name==='stock-add')return stockDialog(el.dataset.kind||'pantry');
 if(name==='stock-remove'){if(!requireUser())return;await store.remove(id);render();return;}
 if(name==='pantry-search'){filters.pantry=true;filters.category='Dinner';return headcountDialog(runSearch);}
 if(name==='leftover-search'){filters.leftovers=true;filters.category='Leftover Recipes';return headcountDialog(runSearch);}
 if(name==='family-add')return familyDialog();
 if(name==='family-edit')return familyDialog(s.family.find(x=>x._id===id));
 if(name==='vote')return voteDialog(id);
 if(name==='custom')return customDialog();
 if(name==='custom-edit')return customDialog(s.custom.find(x=>x.id===id||x._id==='recipe:'+id));
 if(name==='exclusions'){return modal('Your food rules come first',`<form id="exclusionsForm"><label>Exclude ingredients or allergens, separated by commas<textarea name="exclusions" rows="4" maxlength="1000" placeholder="potato, paneer, onion, garlic, nuts, gluten, fried foods">${esc(s.exclusions.join(', '))}</textarea></label><p>Exclusions are never relaxed. Recipes with incomplete ingredient lists are also excluded when a hard exclusion is set.</p><button class="primary wide">Save exclusions</button></form>`);}
 if(name==='equipment'){if(!requireUser())return;const selected=store.value('config:equipment',[]);return modal('What does your kitchen have?',`<form id="equipmentForm"><p>When selected, required equipment becomes a hard filter.</p>${['Tilting pan','Steam kettle','Rice boiler','Tandoor','Fryer','Oven','Dosa plate','Chapati machine','Cold room','Blender'].map(x=>`<label class="check-row"><input type="checkbox" name="equipment" value="${x}" ${selected.includes(x)?'checked':''}>${x}</label>`).join('')}<button class="primary wide">Save equipment</button></form>`);}
 if(name==='weather'){if(!await put('config','config:weather',{kind:el.dataset.value,source:'manual'}))return;notify('Weather preference saved.');return;}
 if(name==='location'){if(!requireUser())return;if(!navigator.geolocation)throw Error('Location is unavailable. Choose weather manually.');navigator.geolocation.getCurrentPosition(async p=>{try{const r=await fetch('/api/weather?'+new URLSearchParams({lat:p.coords.latitude.toFixed(2),lon:p.coords.longitude.toFixed(2)}));const w=await r.json();if(!w.ok)throw Error('Weather is unavailable. Choose it manually.');await put('config','config:weather',{kind:w.kind,temperature:w.temperature,source:'location'});notify('Weather updated.');}catch(e){error(e);}},()=>notify('Location unavailable. You can choose weather manually.'),{timeout:8000,maximumAge:600000});return;}
 if(name==='start-cooking'){step=0;return showCooking();}
 if(name==='step-prev'){step=Math.max(0,step-1);return showCooking();}
 if(name==='step-next'){if(step<activeRecipe.steps.length-1){step++;return showCooking();}return cookDialog([activeRecipe.id],activeRecipe.name);}
 if(name==='step-repeat'){if('speechSynthesis'in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(translate(activeRecipe.steps[step]));utterance.lang=getLocale();speechSynthesis.speak(utterance);}else notify(activeRecipe.steps[step]);return;}
 if(name==='timer-remove'){timers=timers.filter(t=>t.id!==id);drawTimers();return;}
 if(name==='troubleshoot')return modal('A little help at the hob',`<p>Practical kitchen tips. Use your judgement for the particular recipe.</p><details open><summary>My gravy is too thin</summary><p>Simmer uncovered gently, stirring often. Add a small amount of the recipe’s cooked dal or vegetable puree where appropriate. Thickening changes quantities and flavour.</p></details><details><summary>My dal is too salty</summary><p>Add unsalted cooked dal and some water. Simmer and taste again; dilution works better than adding a raw potato.</p></details><details><summary>My paneer became hard</summary><p>Stop prolonged boiling. Try a brief soak in warm water and return it to a gentle sauce near serving time.</p></details><details><summary>My dhokla did not rise</summary><p>Check fresh leavening, batter consistency and a preheated steamer for your recipe. Mix the raising agent only just before steaming.</p></details><button class="secondary" data-action="start-cooking">Back to cooking</button>`);
 if(name==='grocery-copy'){await navigator.clipboard.writeText((fillGrocery.items||[]).map(i=>translate(i.name)+' — '+displayQuantity(i)).join('\n'));notify('Grocery list copied.');return;}
 if(name==='signout'){const old=store;await old?.sync();const result=await client.auth.signOut({scope:'local'});if(result.error)throw result.error;await activateUser(null);nav('today');notify('Signed out. Private data is no longer displayed.');return;}
 if(name==='sync'){if(store)await store.sync();else showAuth();return;}
 if(name==='conflict-local'||name==='conflict-cloud'){await store.resolve(id,name==='conflict-local');render();return;}
 if(name==='export'){if(!requireUser())return;const blob=new Blob([JSON.stringify({version:VERSION,exportedAt:new Date().toISOString(),records:[...store.rows.values()].filter(r=>!r.deleted_at)},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='my-kitchen-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(name==='delete-account')return deletionDialog();
 if(name==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else modal('Your kitchen, one tap away',`<p>Installation is optional. You can always use this website directly.</p><p>On Android Chrome, open the browser menu and choose <b>Install app</b> or <b>Add to Home screen</b>. On iPhone, choose Share → Add to Home Screen.</p><p>The recipes you open are available offline after loading. Account sign-in and first-time content downloads need a connection.</p>`);return;}
}
function slotPicker(){modal('What belongs here?',`<p>${esc(planTarget.date)} · ${esc(planTarget.meal)}</p><div class="menu-actions"><button data-action="slot-discover">Discover dishes</button>${basket.length?'<button data-action="slot-basket">Use my current menu selection</button>':''}${state().combos.map(c=>`<button data-action="slot-combo" data-id="${esc(c._id)}">${esc(c.name)}</button>`).join('')}</div>`);}
const split=x=>String(x||'').split(',').map(v=>toEnglishSearch(v).trim()).filter(Boolean);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-nav]');if(!el)return;e.preventDefault();if(el.dataset.nav){close();nav(el.dataset.nav);return;}Promise.resolve(action(el.dataset.action,el)).catch(error);});
document.addEventListener('submit',async e=>{
 e.preventDefault();const submitOwner=user?.id;const form=e.target,f=new FormData(form),v=Object.fromEntries(f),submit=form.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;
 try{
  if(form.getAttribute('id')==='authForm')return await submitAuth(form);
  if(form.getAttribute('id')==='partyForm'){const next={...party,...v,adults:Number(v.adults),kids:Number(v.kids),guests:Number(v.guests),jainMeals:Number(v.jainMeals||0),buffer:Number(v.buffer||0),budget:Number(v.budget)};headcount(next);if(!Number.isFinite(next.budget)||next.budget<0)throw Error('Enter a valid budget.');party=next;filters.jain=f.has('householdJain')||party.jainMeals>0;household.confirmed=true;await saveHousehold();const callback=saveCallback;close();if(callback)await callback();else render();return;}
  if(form.getAttribute('id')==='heroSearch'||form.getAttribute('id')==='discoverForm'){if(form.getAttribute('id')==='discoverForm')filters={...filters,category:v.category,cuisine:v.cuisine,time:Number(v.time),effort:v.effort,jain:f.has('jain'),query:v.query};const parsed=parseSearch(toEnglishSearch(v.query||''));for(const key of ['category','cuisine','time','effort'])if(explicitFilters.has(key)||(key!=='category'&&filters[key]&&filters[key]!=='Any'))delete parsed[key];filters={...filters,...parsed,jain:filters.jain||parsed.jain};if(parsed.adults!==undefined)party.adults=parsed.adults;if(parsed.kids!==undefined)party.kids=parsed.kids;if(parsed.budget)party.budget=parsed.budget;return headcountDialog(runSearch);}
  if(form.getAttribute('id')==='recipeScaleForm'){recipeParty={...recipeParty,adults:Number(v.adults),kids:Number(v.kids),guests:Number(v.guests),buffer:Number(v.buffer||0)};headcount(recipeParty);showRecipe();return;}
  if(form.getAttribute('id')==='timerForm'){timers.push({id:uid(),name:v.name.trim(),end:Date.now()+Number(v.minutes)*60000});drawTimers();notify('Timer set. Keep the app open for its alert.');return;}
  if(form.getAttribute('id')==='exclusionsForm'){household.exclusions=split(v.exclusions);if(user)await put('config','config:exclusions',household.exclusions);await saveHousehold();close();results=[];searchCompleted=false;render();notify('Hard exclusions saved.');return;}
  if(!requireUser())return;
  if(form.getAttribute('id')==='profileForm'){await put('profile','profile:me',{name:v.name.trim(),skill:v.skill});render();notify('Profile saved.');return;}
  if(form.getAttribute('id')==='comboForm'){const ids=f.getAll('dishIds');if(!ids.length)throw Error('Choose at least one dish.');const c={name:v.name.trim(),dishIds:ids,dishNames:ids.map(id=>dishes.get(id)?.name||id),notes:v.notes.trim(),cuisine:v.cuisine.trim(),occasion:v.occasion.trim(),tags:split(v.tags),favorite:f.has('favorite'),party:{...(comboEditor.current?.party||party)}};await put('combo',v.id||'combo:'+uid(),c);basket=[];close();nav('combos');notify('Menu saved to your kitchen.');return;}
  if(form.getAttribute('id')==='planForm'){await savePlan(v.date,v.meal,planDialog.ids,v.name.trim());if(f.has('repeat'))await put('recurrence','recurrence:'+new Date(v.date+'T12:00:00').getDay()+':'+v.meal,{weekday:new Date(v.date+'T12:00:00').getDay(),meal:v.meal,dishIds:planDialog.ids,name:v.name,party:{...party}});close();nav('planner');notify('Meal saved to your calendar.');return;}
  if(form.getAttribute('id')==='duplicateDayForm'){if(v.target===v.source)throw Error('Choose a different day.');await loadCategories(MEALS);let copied=0,skipped=0;for(const p of state().plans.filter(x=>x.date===v.source)){if(state().plans.some(x=>x.date===v.target&&x.meal===p.meal))continue;try{await savePlan(v.target,p.meal,p.dishIds,p.name);copied++;}catch{skipped++;}}close();render();notify(`${copied} meals copied; ${skipped} skipped because of food rules.`);return;}
  if(form.getAttribute('id')==='stockForm'){if(!vegetarianText(toEnglishSearch(v.name)))throw Error('This kitchen is vegetarian and eggless.');await put(v.kind,v.kind+':'+uid(),{name:toEnglishSearch(v.name),quantity:toEnglishSearch(v.quantity),expiry:v.expiry||null});close();nav('pantry');return;}
  if(form.getAttribute('id')==='familyForm'){await put('family',v.id||'family:'+uid(),{name:v.name.trim(),child:f.has('child'),likes:split(v.likes),dislikes:split(v.dislikes),cuisines:split(v.cuisines),spice:v.spice,diet:v.diet.trim()});close();nav('family');return;}
  if(form.getAttribute('id')==='voteForm'){const values={};for(const p of state().family)values[p._id]=Number(f.get(p._id)||0);await put('vote','vote:'+v.dishId,{dishId:v.dishId,value:values});close();notify('Family votes saved.');return;}

  if(form.getAttribute('id')==='equipmentForm'){await put('config','config:equipment',f.getAll('equipment'));close();render();return;}
  if(form.getAttribute('id')==='customForm'){if(!vegetarianText(toEnglishSearch(v.name+' '+v.ingredients+' '+v.steps)))throw Error('Only vegetarian, eggless recipes are allowed.');const ingredients=v.ingredients.split('\n').filter(x=>x.trim()).map(line=>{const [name,qty,unit]=line.split(',').map(x=>toEnglishSearch(x).trim());if(!name||!Number.isFinite(Number(qty))||Number(qty)<=0||!['g','kg','ml','l','piece','slice'].includes(unit))throw Error('Use one ingredient per line: name, quantity, g / kg / ml / l / piece / slice.');return {name,qty:Number(qty),unit,group:'Other',scale:'linear'};});if(!ingredients.length)throw Error('Add your ingredients.');const privateInput=form.querySelector('#privatePhotoInput');const privatePhoto=privateInput?.files?.[0]?await features.resizePrivatePhoto(privateInput.files[0]):state().custom.find(x=>x._id===v.id)?.privatePhoto;if(submitOwner!==user?.id)throw Error('Account changed. Open this form again.');const id=v.id?v.id.slice(7):'family-'+uid(),recipe={id,privatePhoto,name:v.name.trim(),author:v.author,cuisine:v.cuisine,categories:[v.category],time:Number(v.time),ingredients,steps:v.steps.split('\n').map(x=>x.trim()).filter(Boolean),notes:v.notes,baseServings:4,status:'complete',vegetarian:true,eggless:true,jainVerified:!ROOTS.test(ingredients.map(x=>x.name).join(' ')),nutrition:['balanced']};await put('recipe','recipe:'+id,recipe);customDishes().forEach(d=>dishes.set(d.id,d));close();notify('Private family recipe saved.');return;}
  if(form.getAttribute('id')==='cookedForm'){const ids=cookDialog.ids.map(canonical),rating=Number(v.rating);await put('history','history:'+uid(),{name:cookDialog.name,date:new Date().toISOString(),dishIds:ids,canonicalIds:ids,party:{...party},rating,comments:v.comments,cost:ids.length>1?openBasket.cost||null:null,cuisine:dishes.get(ids[0])?.cuisine});for(const id of ids){const p=state().preferences[id]||{},r=state().ratings[id]||{sum:0,count:0};await put('preference','preference:'+id,{dishId:id,value:{...p,cooked:(p.cooked||0)+1}});await put('rating','rating:'+id,{dishId:id,value:{sum:r.sum+rating,count:r.count+1}});}results=results.filter(d=>!ids.includes(d.id));close();nav('combos');notify('Remembered. Here’s to a good meal.');return;}
  if(form.getAttribute('id')==='deleteForm'){const {data}=await client.auth.getSession();if(!data.session)throw Error('Sign in again before deleting.');const r=await fetch('/api/delete-account',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session.access_token},body:JSON.stringify({confirmation:v.confirmation})});const data2=await r.json();if(!r.ok)throw Error(data2.error);await store.erase();await client.auth.signOut({scope:'local'});await activateUser(null);close();nav('today');notify('Your account and private kitchen data have been deleted.');return;}
 }catch(e){const target=form.querySelector('.form-error');if(target)target.textContent=e.message;else error(e);}finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-metric-units]')){household.metric=el.checked;saveHousehold().then(()=>{if($('#dialog').open&&activeRecipe)showRecipe();else render();}).catch(error);return;}if(el.matches('[data-household-jain],#discoverForm [name="jain"]')){filters.jain=el.checked;saveHousehold().catch(error);return;}if(el.id==='kitchenExperience'){party={...party,mode:el.value,buffer:0,jainMeals:0};saveHousehold().then(render).catch(error);return;}if(el.closest('#discoverForm')&&['category','cuisine','time','effort'].includes(el.name))explicitFilters.add(el.name);if(el.dataset.grocery){put('grocery','grocery:'+el.dataset.grocery,{checked:el.checked}).catch(error);}const flags={largeText:'large-text',highContrast:'high-contrast',reducedMotion:'reduced-motion'};if(flags[el.id]){document.body.classList.toggle(flags[el.id],el.checked);try{localStorage.setItem('kkk-accessibility',JSON.stringify(Object.values(flags).filter(k=>document.body.classList.contains(k))));}catch{}}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-dish]');if(card)e.dataTransfer.setData('text/plain',card.dataset.dish);});
document.addEventListener('dragover',e=>{if(e.target.closest('.calendar-slot'))e.preventDefault();});
document.addEventListener('drop',e=>{const slot=e.target.closest('.calendar-slot');if(!slot)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!dishes.has(id))return;planTarget={date:slot.dataset.date,meal:slot.dataset.meal};headcountDialog(()=>planDialog([id]));});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>{updateSync();store?.sync();});window.addEventListener('offline',updateSync);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')store?.sync();});
setInterval(()=>store?.sync(),45000);
try{for(const c of JSON.parse(localStorage.getItem('kkk-accessibility')||'[]'))if(['large-text','high-contrast','reduced-motion'].includes(c))document.body.classList.add(c);}catch{}
features=installFeatures({user:()=>user,store:()=>store,view:()=>currentView,config:()=>config,client:()=>client,state,party:()=>party,filters:currentFilters,week:()=>week,basket:()=>basket,setBasket:ids=>basket=ids,activeRecipe:()=>activeRecipe,recipeFor,openRecipe,openBasket,showCooking,modal,close,notify,error,nav,put,requireUser,headcountDialog,cookingAction:name=>action(name,{}),addTimer:(name,minutes)=>{timers.push({id:uid(),name,end:Date.now()+minutes*60000});drawTimers();},search:next=>{filters={...filters,...next,jain:filters.jain||next.jain};for(const key of ['adults','kids','budget'])if(next[key]>0)party[key]=next[key];return headcountDialog(runSearch);}});
